import { readFile } from "node:fs/promises";
import { resolve, sep, extname } from "node:path";

// Pagefind is generated by `pnpm build`. Serve that snapshot in development too.
export function devSearchIndex() {
  return {
    name: "local-pagefind-index",
    configureServer(server) {
      const root = resolve(server.config.root, "dist/pagefind");
      server.middlewares.use(async (req, res, next) => {
        const pathname = new URL(req.url ?? "/", "http://localhost").pathname;
        if (!pathname.startsWith("/pagefind/")) return next();
        const relative = pathname.slice("/pagefind/".length);
        if (!/^[a-zA-Z0-9_./-]+$/.test(relative)) return next();
        const file = resolve(root, relative);
        if (!file.startsWith(root + sep)) return next();
        try {
          const body = await readFile(file);
          const types = {
            ".js": "text/javascript",
            ".json": "application/json",
            ".wasm": "application/wasm",
          };
          res.setHeader("Content-Type", types[extname(file)] ?? "application/octet-stream");
          res.setHeader("Cache-Control", "no-store");
          res.end(body);
        } catch {
          res.statusCode = 404;
          res.end("Build the local search index with pnpm build.");
        }
      });
    },
  };
}
